import{_ as s,a0 as e,w as u,s as d,ao as p,I as i,x as n,a1 as r,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"進入 Linux 桌面之窗 | LCTT x X-CMD","titleTemplate":false,"description":"進入 Linux 桌面之窗 | LCTT (201710) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"進入 Linux 桌面之窗 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"進入 Linux 桌面之窗 | LCTT (201710) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201710/20170421 A Window Into the Linux Desktop","title":"進入 Linux 桌面之窗","tag":"201710","desc":""},"relativePath":"201710/20170421 A Window Into the Linux Desktop.md","filePath":"[post].md"}'),a={name:"201710/20170421 A Window Into the Linux Desktop.md"};function x(m,t,w,T,f,L){const l=e("Link");return u(),d("div",null,[t[25]||(t[25]=p('<h1 id="進入-linux-桌面之窗" tabindex="-1">進入 Linux 桌面之窗 <a class="header-anchor" href="#進入-linux-桌面之窗" aria-label="Permalink to “進入 Linux 桌面之窗”">​</a></h1><p><img src="http://www.linuxinsider.com/article_images/story_graphics_xlarge/xl-2016-linux-1.jpg" alt="linux-desktop"></p><blockquote><p>“它能做什麼 Windows 不能做的嗎？”</p></blockquote><p>這是許多人在考慮使用 Linux 桌面時的第一個問題。雖然支撐 Linux 的開源哲學對於某些人來説就是一個很好的理由，但是有些人想知道它在外觀、感受和功能上有多麼不同。在某種程度上，這取決於你是否選擇桌面環境或窗口管理器。</p><p>如果你想要的是閃電般快速的桌面體驗且向高效妥協, 那麼上述的經典桌面中的窗口管理器可能適合你。</p><h3 id="事實之真相" tabindex="-1">事實之真相 <a class="header-anchor" href="#事實之真相" aria-label="Permalink to “事實之真相”">​</a></h3><p>“<ruby>桌面環境<rt>Desktop Environment</rt></ruby>（DE）”是一個技術術語，指典型的、全功能桌面，即你的操作系統的完整圖形化佈局。除了顯示你的程序，桌面環境還包括應用程序啓動器，菜單面板和小部件等組成部分。</p><p>在 Microsoft Windows 中，桌面環境包括開始菜單、顯示打開的程序的任務欄和通知中心，還有與操作系統捆綁在一起的所有 Windows 程序，以及圍繞這打開的程序的框架（包括右上角的最小按鈕、最大按鈕和關閉按鈕）。</p><p>Linux 中有很多相似之處。</p>',9)),i("p",null,[t[1]||(t[1]=n("例如，Linux ",-1)),r(l,{href:"http://en.wikipedia.org/wiki/GNOME"},{default:o(()=>[...t[0]||(t[0]=[n("Gnome",-1)])]),_:1}),t[2]||(t[2]=n(" 桌面環境的設計略有不同，但它共享了所有的 Microsoft Windows 的基本元素 - 從應用程序菜單到顯示打開的應用程序的面板、通知欄、窗框式程序。",-1))]),t[26]||(t[26]=p('<p>窗口程序框架依賴於一個組件來繪製它們，並允許你移動並調整大小：它被稱為“<ruby>窗口管理器<rt>Window Manager</rt></ruby>（WM）”。因為它們都有窗口，所以每個桌面環境都包含一個窗口管理器。</p><p>然而，並不是每個窗口管理器都是桌面環境的一部分。你可以只運行窗口管理器，並且完全有這麼做的需要。</p><h3 id="離開你的環境" tabindex="-1">離開你的環境 <a class="header-anchor" href="#離開你的環境" aria-label="Permalink to “離開你的環境”">​</a></h3><p>對本專欄而言，所謂的“窗口管理器”指的是可以那種獨立進行的。如果在現有的 Linux 系統上安裝了一個窗口管理器，你可以在不關閉系統的情況下注銷，在登錄屏幕上選擇新的窗口管理器，然後重新登錄。</p><p>不過, 在研究你的窗口管理器之前，你可能不想這麼做，因為你將會看到一個空白屏幕和稀疏的狀態欄，而且它或許能、或許不能點擊。</p><p>通常情況下，可以直接在窗口管理器中直接啓動終端，因為這是你編輯其配置文件的方式。在那裏你會發現用來啓動程序的按鍵和鼠標組合，你實際上也可以使用你的新設置。</p><p>例如，在流行的 i3 窗口管理器中，你可以通過按下 <code>Super</code> 鍵（即 <code>Windows</code> 鍵）加 <code>Enter</code> 鍵來啓動終端，或者按 <code>Super + D</code> 啓動<ruby>應用程序啓動器<rt>app launcher</rt></ruby>。你可以在其中輸入應用程序名稱，然後按 <code>Enter</code> 鍵將其打開。所有已有的應用程序都可以通過這種方式找到，一旦選擇後，它們將會全屏打開。</p>',7)),i("p",null,[r(l,{href:"http://www.linuxinsider.com/article_images/2017/84473_1200x750.jpg"},{default:o(()=>[...t[3]||(t[3]=[i("img",{src:"http://www.linuxinsider.com/article_images/2017/84473_620x388-small.jpg",alt:"i3 window manager"},null,-1)])]),_:1})]),t[27]||(t[27]=i("p",null,"i3 還是一個平鋪式窗口管理器，這意味着它可以確保所有的窗口均勻地擴展到屏幕，既不重疊也不浪費空間。當彈出新窗口時，它會減少現有的窗口，將它們推到一邊騰出空間。用户可以以垂直或水平相鄰的方式打開下一個窗口。",-1)),t[28]||(t[28]=i("h3",{id:"功能亦敵亦友",tabindex:"-1"},[n("功能亦敵亦友 "),i("a",{class:"header-anchor",href:"#功能亦敵亦友","aria-label":"Permalink to “功能亦敵亦友”"},"​")],-1)),t[29]||(t[29]=i("p",null,"當然，桌面環境有其優點。首先，它們提供功能豐富、可識別的界面。每個都有其特徵鮮明的風格，但總體而言，它們提供了普適的默認設置，這使得桌面環境從一開始就可以使用。",-1)),t[30]||(t[30]=i("p",null,"另一個優點是桌面環境帶有一組程序和媒體編解碼器，允許用户立即完成簡單的任務。此外，它們還包括一些方便的功能，如電池監視器、無線小部件和系統通知。",-1)),t[31]||(t[31]=i("p",null,"與桌面環境的完善相應的，是這種大型軟件庫和用户體驗理念獨一無二，這就意味着它們所能做的都是有限度的。這也意味着它們並不總是非常可配置。桌面環境強調的是漂亮的外表，很多時候是金玉其外的。",-1)),t[32]||(t[32]=i("p",null,"許多桌面環境對系統資源的渴求是眾所周知的，所以它們不太喜歡低端硬件。因為在其上運行的視覺效果，還有更多的東西可能會出錯。我曾經嘗試調整與我正在運行的桌面環境無關的網絡設置，然後整個崩潰了。而當我打開一個窗口管理器，我就可以改變設置。",-1)),t[33]||(t[33]=i("p",null,"那些優先考慮安全性的人可能希望不要桌面環境，因為更多的程序意味着更大的攻擊面 —— 也就是壞人可以突破的入口點。",-1)),t[34]||(t[34]=i("p",null,"然而，如果你想嘗試一下桌面環境，XFCE 是一個很好的起點，因為它的較小的軟件庫消除了一些臃腫，如果你不往裏面塞東西，垃圾就會更少。",-1)),i("p",null,[t[5]||(t[5]=n("乍一看，它不是最漂亮的，但在下載了一些 GTK 主題包（每個桌面環境都可以提供這些主題或 Qt 主題，而 XFCE 在 GTK 陣營之中），並且在“外觀”部分的設置中，你可以輕鬆地修改。你甚至可以在這個",-1)),r(l,{href:"http://www.xfce-look.org/"},{default:o(()=>[...t[4]||(t[4]=[n("集中式畫廊",-1)])]),_:1}),t[6]||(t[6]=n("中找到你最喜歡的主題。",-1))]),t[35]||(t[35]=p('<h3 id="時間就是生命" tabindex="-1">時間就是生命 <a class="header-anchor" href="#時間就是生命" aria-label="Permalink to “時間就是生命”">​</a></h3><p>如果你想了解桌面環境之外可以做什麼，你會發現窗口管理器給了你足夠的迴旋餘地。</p><p>無論如何，窗口管理器都是與定製有關的。事實上，它們的可定製性已經催生了無數的畫廊，承載着一個充滿活力的社區用户，他們手中的調色板就是窗口管理器。</p><p>窗口管理器的少量資源需求使它們成為較低規格硬件的理想選擇，並且由於大多數窗口管理器不附帶任何程序，因此允許喜歡模組化的用户只添加所需的程序。</p><p>可能與桌面環境最為顯著的區別是，窗口管理器通常通過鼠標移動和鍵盤熱鍵來打開程序或啓動器來聚焦效率。</p><p>鍵盤驅動的窗口管理器特別流暢，你可以啓動新的窗口、輸入文本或更多的鍵盤命令、移動它們，並再次關閉它們，這一切無需將手從<ruby>鍵盤中間<rt>home row</rt></ruby>移開。一旦你適應了其設計邏輯，你會驚訝於你能夠如此快速地完成任務。</p><p>儘管它們提供了自由，窗口管理器也有其缺點。最顯著的是，它們是赤裸裸的開箱即用。在你可以使用其中一個之前，你必須花時間閲讀窗口管理器的文檔以獲取配置語法，可能還需要更多的時間來找到該語法的竅門。</p><p>如果你從桌面環境（這是最可能的情況）切換過來，儘管你會有一些用户程序，你也會缺少一些熟悉的東西，如電池指示器和網絡小部件，並且需要一些時間來設置新的。</p>',8)),i("p",null,[t[8]||(t[8]=n("如果你想深入窗口管理器，i3 有",-1)),r(l,{href:"https://i3wm.org/docs/"},{default:o(()=>[...t[7]||(t[7]=[n("完整的文檔",-1)])]),_:1}),t[9]||(t[9]=n("和簡明直白的配置語法。配置文件不使用任何編程語言 - 它只是每行定義一個變量值對。創建熱鍵只要輸入 ",-1)),t[10]||(t[10]=i("code",null,"bindsym",-1)),t[11]||(t[11]=n("、鍵盤綁定以及該組合啓動的動作即可。",-1))]),t[36]||(t[36]=i("p",null,"雖然窗口管理器不適合每個人，但它們提供了獨特的計算體驗，而 Linux 是少數允許使用它們的操作系統之一。無論你最終採用哪種模式，我希望這個概觀能夠給你足夠的信息，以便對你所做的選擇感到自信 —— 或者有足夠的信心跨出您熟悉的區域來看看還有什麼可用的。",-1)),t[37]||(t[37]=i("hr",null,null,-1)),t[38]||(t[38]=i("p",null,"作者簡介：",-1)),t[39]||(t[39]=i("p",null,"Jonathan Terrasi - 自 2017 年以來一直是 ECT 新聞網專欄作家。他的主要興趣是計算機安全（特別是 Linux 桌面）、加密和分析政治和時事。他是全職自由作家和音樂家。他的背景包括在芝加哥委員會發表的關於維護人權法案的文章中提供技術評論和分析。",-1)),t[40]||(t[40]=i("hr",null,null,-1)),i("p",null,[t[13]||(t[13]=n("via: ",-1)),r(l,{href:"http://www.linuxinsider.com/story/84473.html"},{default:o(()=>[...t[12]||(t[12]=[n("http://www.linuxinsider.com/story/84473.html",-1)])]),_:1})]),i("p",null,[t[17]||(t[17]=n("作者：",-1)),r(l,{href:"%5B1%5D:http://www.linuxinsider.com/story/84473.html?rss=1#"},{default:o(()=>[...t[14]||(t[14]=[n("Jonathan Terrasi",-1)])]),_:1}),t[18]||(t[18]=n(" 譯者：",-1)),r(l,{href:"https://github.com/geekpi"},{default:o(()=>[...t[15]||(t[15]=[n("geekpi",-1)])]),_:1}),t[19]||(t[19]=n(" 校對：",-1)),r(l,{href:"https://github.com/wxy"},{default:o(()=>[...t[16]||(t[16]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[22]||(t[22]=n("本文由 ",-1)),r(l,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[20]||(t[20]=[n("LCTT",-1)])]),_:1}),t[23]||(t[23]=n(" 原創編譯，",-1)),r(l,{href:"https://linux.cn/"},{default:o(()=>[...t[21]||(t[21]=[n("Linux中國",-1)])]),_:1}),t[24]||(t[24]=n(" 榮譽推出",-1))])])}const k=s(a,[["render",x]]);export{C as __pageData,k as default};
